create schema if not exists "game";

create table "game"."accessory" (
    "id" smallint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now()
);


alter table "game"."accessory" enable row level security;

create table "game"."accessory_translation" (
    "id" smallint generated by default as identity not null,
    "accessory_id" smallint not null,
    "language" character varying not null default 'en'::character varying,
    "name" character varying not null
);


alter table "game"."accessory_translation" enable row level security;

create table "game"."action_card" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now()
);


alter table "game"."action_card" enable row level security;

create table "game"."action_card_settings" (
    "id" integer generated by default as identity not null,
    "game_id" integer not null,
    "state_id" smallint not null,
    "card_limit" smallint,
    "card_seconds" smallint,
    "is_auto_next" boolean not null default false,
    "is_player_creative" boolean not null default false,
    "has_buzzer" boolean not null default false,
    "created_at" timestamp with time zone not null default now(),
    "allow_sentence" boolean not null default true,
    "can_repeat" boolean not null default false,
    "card_based_timer" boolean not null default false,
    "exclude_players_amount" character varying,
    "one_card_per_player" boolean not null default false
);


alter table "game"."action_card_settings" enable row level security;

create table "game"."action_card_settings_has_action_card" (
    "action_card_settings_id" integer not null,
    "action_card_id" bigint not null
);


alter table "game"."action_card_settings_has_action_card" enable row level security;

create table "game"."action_card_settings_translation" (
    "id" integer generated by default as identity not null,
    "action_card_settings_id" integer not null,
    "language" character varying not null default 'en'::character varying,
    "prompt" text,
    "player_creative_prompt" text
);


alter table "game"."action_card_settings_translation" enable row level security;

create table "game"."action_card_state" (
    "id" smallint generated by default as identity not null,
    "name" character varying not null
);


alter table "game"."action_card_state" enable row level security;

create table "game"."action_card_translation" (
    "id" bigint generated by default as identity not null,
    "action_card_id" bigint not null,
    "language" character varying not null default 'en'::character varying,
    "value" text not null
);


alter table "game"."action_card_translation" enable row level security;

create table "game"."challenge" (
    "id" integer generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "message" text not null
);


alter table "game"."challenge" enable row level security;

create table "game"."game" (
    "id" integer generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "min_players" smallint not null default '2'::smallint,
    "max_players" smallint,
    "activity_level" smallint not null default '0'::smallint,
    "minutes" smallint not null default '1'::smallint,
    "game_category_id" smallint not null,
    "game_audience_id" smallint,
    "drunk_level" smallint not null default '0'::smallint,
    "game_end_type" text not null default 'finish'::text,
    "name" character varying not null,
    "deleted_at" timestamp with time zone,
    "has_winner" boolean not null default false,
    "active" boolean not null default false,
    "custom_rules_image" character varying
);


alter table "game"."game" enable row level security;

create table "game"."game_audience" (
    "id" smallint generated by default as identity not null,
    "name" character varying not null
);


alter table "game"."game_audience" enable row level security;

create table "game"."game_category" (
    "id" smallint generated by default as identity not null,
    "name" character varying not null
);


alter table "game"."game_category" enable row level security;

create table "game"."game_has_accessory" (
    "id" integer generated by default as identity not null,
    "game_id" integer not null,
    "accessory_id" smallint not null
);


alter table "game"."game_has_accessory" enable row level security;

create table "game"."game_has_game_type" (
    "id" integer generated by default as identity not null,
    "game_id" integer not null,
    "game_type_id" smallint not null
);


alter table "game"."game_has_game_type" enable row level security;

create table "game"."game_translation" (
    "id" integer generated by default as identity not null,
    "game_id" integer not null,
    "language" character varying not null default 'en'::character varying,
    "name" character varying not null,
    "custom_end_game_sentence" text,
    "has_winner_prompt" text,
    "descriptions" jsonb not null default '{}'::jsonb
);


alter table "game"."game_translation" enable row level security;

create table "game"."game_type" (
    "id" smallint generated by default as identity not null,
    "name" character varying not null,
    "created_at" timestamp with time zone not null default now()
);


alter table "game"."game_type" enable row level security;

CREATE UNIQUE INDEX accessory_pkey ON game.accessory USING btree (id);

CREATE UNIQUE INDEX accessory_translation_pkey ON game.accessory_translation USING btree (id);

CREATE UNIQUE INDEX action_card_pkey ON game.action_card USING btree (id);

CREATE UNIQUE INDEX action_card_settings_has_action_card_pkey ON game.action_card_settings_has_action_card USING btree (action_card_settings_id, action_card_id);

CREATE UNIQUE INDEX action_card_settings_pkey ON game.action_card_settings USING btree (id);

CREATE UNIQUE INDEX action_card_settings_translation_pkey ON game.action_card_settings_translation USING btree (id);

CREATE UNIQUE INDEX action_card_state_name_key ON game.action_card_state USING btree (name);

CREATE UNIQUE INDEX action_card_state_pkey ON game.action_card_state USING btree (id);

CREATE UNIQUE INDEX action_card_translation_pkey ON game.action_card_translation USING btree (id);

CREATE UNIQUE INDEX challenge_pkey ON game.challenge USING btree (id);

CREATE UNIQUE INDEX game_accessory_unique ON game.game_has_accessory USING btree (game_id, accessory_id);

CREATE UNIQUE INDEX game_audience_type_name_key ON game.game_audience USING btree (name);

CREATE UNIQUE INDEX game_audience_type_pkey ON game.game_audience USING btree (id);

CREATE UNIQUE INDEX game_category_name_key ON game.game_category USING btree (name);

CREATE UNIQUE INDEX game_category_pkey ON game.game_category USING btree (id);

CREATE UNIQUE INDEX game_has_accessory_pkey ON game.game_has_accessory USING btree (id);

CREATE UNIQUE INDEX game_has_game_type_pkey ON game.game_has_game_type USING btree (id);

CREATE UNIQUE INDEX game_has_game_type_unique ON game.game_has_game_type USING btree (game_id, game_type_id);

CREATE UNIQUE INDEX game_name_key ON game.game USING btree (name);

CREATE UNIQUE INDEX game_pkey ON game.game USING btree (id);

CREATE UNIQUE INDEX game_translation_pkey ON game.game_translation USING btree (id);

CREATE UNIQUE INDEX game_type_name_unique ON game.game_type USING btree (name);

CREATE UNIQUE INDEX game_type_pkey ON game.game_type USING btree (id);

