create schema if not exists "player";

create sequence "player"."player_username_seq";

create table "player"."player" (
    "id" uuid not null default gen_random_uuid(),
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "username" character varying,
    "is_guest" boolean not null default false,
    "user_id" uuid,
    "avatar_color" character varying
);


alter table "player"."player" enable row level security;

create table "player"."player_has_action_card" (
    "player_id" uuid not null,
    "room_id" integer not null,
    "action_card_id" smallint,
    "used_action_card_ids" smallint[],
    "last_player_id" uuid,
    "card_count" smallint
);


alter table "player"."player_has_action_card" enable row level security;

create table "player"."player_has_room" (
    "player_id" uuid not null,
    "room_id" integer not null,
    "joined_at" timestamp with time zone not null default now(),
    "last_seen" timestamp with time zone not null default now(),
    "paused" boolean not null default false
);


alter table "player"."player_has_room" enable row level security;

create table "player"."room" (
    "id" integer generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "max_players" smallint not null default '15'::smallint,
    "name" character varying not null,
    "host_player_id" uuid not null,
    "in_game" boolean not null default false
);


alter table "player"."room" enable row level security;

create table "player"."room_event" (
    "id" uuid not null default gen_random_uuid(),
    "created_at" timestamp with time zone not null default now(),
    "room_id" integer not null,
    "event" character varying not null,
    "payload" jsonb not null
);


alter table "player"."room_event" enable row level security;

CREATE UNIQUE INDEX player_has_action_card_pkey ON player.player_has_action_card USING btree (room_id, player_id);

CREATE UNIQUE INDEX player_has_action_card_player_id_key ON player.player_has_action_card USING btree (player_id);

CREATE UNIQUE INDEX player_has_room_pkey ON player.player_has_room USING btree (player_id, room_id);

CREATE UNIQUE INDEX player_pkey ON player.player USING btree (id);

CREATE UNIQUE INDEX player_user_id_key ON player.player USING btree (user_id);

CREATE INDEX room_event_lookup_idx ON player.room_event USING btree (room_id, event, created_at DESC);

CREATE UNIQUE INDEX room_event_pkey ON player.room_event USING btree (id);

CREATE UNIQUE INDEX room_pkey ON player.room USING btree (id);

alter table "player"."player" add constraint "player_pkey" PRIMARY KEY using index "player_pkey";

alter table "player"."player_has_action_card" add constraint "player_has_action_card_pkey" PRIMARY KEY using index "player_has_action_card_pkey";

alter table "player"."player_has_room" add constraint "player_has_room_pkey" PRIMARY KEY using index "player_has_room_pkey";

alter table "player"."room" add constraint "room_pkey" PRIMARY KEY using index "room_pkey";

alter table "player"."room_event" add constraint "room_event_pkey" PRIMARY KEY using index "room_event_pkey";

alter table "player"."player" add constraint "player_player_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "player"."player" validate constraint "player_player_user_id_fkey";

alter table "player"."player" add constraint "player_user_id_key" UNIQUE using index "player_user_id_key";

