set check_function_bodies = off;

CREATE OR REPLACE FUNCTION player.create_player_for_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into player.player (user_id)
  values (new.id);
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION player.delete_old_rooms()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
delete from player.room
where created_at < now() - interval '24 hours';
end;
$function$
;

CREATE OR REPLACE FUNCTION player.set_default_username()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$BEGIN
  -- Only set username if it's NULL
  IF NEW.username IS NULL AND NEW.is_guest = TRUE THEN
    NEW.username := 'User' || nextval('player.player_username_seq');
  END IF;
  RETURN NEW;
END;$function$
;

